use vstd::prelude::*;

verus! {
    // insert_before_each takes a vector `arr` and an element `elem`,
    // and returns a new vector `result` of length 2 * arr.len(),
    // such that for each k < arr.len():
    //   result[2*k]   == elem
    //   result[2*k+1] == arr[k]
    fn insert_before_each(arr: &Vec<i32>, elem: i32) -> (result: Vec<i32>)
        ensures
            // length of the result is twice the length of the input
            result.len() == 2 * arr.len() &&
            // interleaving property
            forall |k: usize| k < arr.len() ==>
                result[2*k] == elem &&
                result[2*k + 1] == arr[k]
    {
        // build up the result by pushing elem and then arr[idx]
        let mut res: Vec<i32> = Vec::new();
        // reserve capacity to avoid reallocations
        res.reserve(2 * arr.len());

        let mut idx: usize = 0;
        while idx < arr.len()
            invariant
                // idx never exceeds the length of arr
                idx <= arr.len(),
                // at each step, we've processed exactly idx elements,
                // so res.len() == 2*idx
                res.len() == 2 * idx,
                // for all processed positions k < idx, the interleaving
                // property holds in res
                forall |k: usize| k < idx ==>
                    res[2*k] == elem &&
                    res[2*k + 1] == arr[k],
            decreases arr.len() - idx,
        {
            // push the interleaved pair for arr[idx]
            res.push(elem);
            res.push(arr[idx]);
            idx = idx + 1;
        }

        // now idx == arr.len(), so res.len() == 2*arr.len()
        res
    }
}

